local function ZUFZO_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.configUS.pingLabel.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_pingLabel"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Stats = game:GetService("Stats")
	
	local pingLabel = script.Parent
	
	pingLabel.BackgroundTransparency = 1
	pingLabel.TextStrokeTransparency = 1
	pingLabel.Visible = true
	
	while true do
		local ping = 0
	
		local success, result = pcall(function()
			return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
		end)
	
		if success and result then
			ping = math.floor(result)
		end
	
		pingLabel.Text = "PING: " .. ping .. " ms"
	
		if ping <= 60 then
			pingLabel.TextColor3 = Color3.fromRGB(0, 255, 0)
		elseif ping <= 120 then
			pingLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
		else
			pingLabel.TextColor3 = Color3.fromRGB(255, 0, 0)
		end
	
		task.wait(1)
	end
end
