		Instance.new("UICorner", btn)
	
		-- IMG
		local img = Instance.new("ImageLabel")
		img.Parent = btn
		img.Size = UDim2.new(1,-10,0,70)
		img.Position = UDim2.new(0,5,0,5)
		img.BackgroundTransparency = 1
		img.ScaleType = Enum.ScaleType.Fit
		img.Image = "rbxthumb://type=Asset&id="..id.."&w=420&h=420"
	
		-- NAME
		local txt = Instance.new("TextLabel")
		txt.Parent = btn
		txt.Size = UDim2.new(1,-30,0,22)
		txt.Position = UDim2.new(0,3,1,-25)
		txt.BackgroundTransparency = 1
		txt.Text = name
		txt.TextScaled = true
		txt.Font = Enum.Font.GothamBold
		txt.TextColor3 = Color3.new(1,1,1)
	
		-- STAR
		local star = Instance.new("TextButton")
		star.Parent = btn
		star.Size = UDim2.new(0,20,0,20)
		star.Position = UDim2.new(1,-24,1,-24)
		star.BackgroundTransparency = 1
		star.TextScaled = true
		star.Font = Enum.Font.GothamBold
		star.TextColor3 = Color3.fromRGB(255,255,0)
	
		if favoritos[idString] then
			star.Text = "?"
		else
			star.Text = "?"
		end
	
		star.MouseButton1Click:Connect(function()
	
			Favoritar(name,id)
	
			if favoritos[idString] then
				star.Text = "?"
			else
				star.Text = "?"
			end
	
			if mostrandoFavoritos then
				pesquisarCatalogo(search.Text)
			end
		end)
	
		btn.MouseButton1Click:Connect(function()
			playEmote(name,id)
		end)
	end
	
	-- REFRESH
	local function refresh(lista)
	
		clearButtons()
	
		for _,info in ipairs(lista) do
			createButton(info[1],info[2])
		end
	
		task.wait()
	
		scroll.CanvasSize = UDim2.new(
			0,
			0,
			0,
			grid.AbsoluteContentSize.Y + 10
		)
	end
	
	-- SEARCH
	function pesquisarCatalogo(texto)
	
		local resultado = {}
	
		texto = string.lower(texto or "")
	
		-- FAVORITOS
		if mostrandoFavoritos then
	
			for _,info in pairs(favoritos) do
	
				if texto == "" or string.find(string.lower(info[1]), texto) then
					table.insert(resultado,info)
				end
			end
	
		else
	
			if texto ~= "" then
	
				local ok, pages = pcall(function()
	
					local params = CatalogSearchParams.new()
					params.SearchKeyword = texto
					params.AssetTypes = {Enum.AvatarAssetType.EmoteAnimation}
					params.SortType = Enum.CatalogSortType.Relevance
					params.Limit = 30
	
					return AvatarEditorService:SearchCatalog(params)
				end)
	
				if ok and pages then
	
					for _,item in ipairs(pages:GetCurrentPage()) do
	
						if item.Name and item.Id then
	
							table.insert(resultado,{
								item.Name,
								item.Id
							})
						end
					end
				end
			end
		end
	
		refresh(resultado)
	end
	
	-- LOAD PLAYER EMOTES
	local function carregarEmotesDoPlayer()
	
		local ok, desc = pcall(function()
			return Players:GetHumanoidDescriptionFromUserId(LocalPlayer.UserId)
		end)
	
		if ok and desc then
	
			local ok2, userEmotes = pcall(function()
				return desc:GetEmotes()
			end)
	
			if ok2 and userEmotes then
	
				for emoteName, ids in pairs(userEmotes) do
	
					if typeof(ids) == "table" then
	
						for _, id in ipairs(ids) do
	
							local idString = tostring(id)
	
							if not favoritos[idString] then
								favoritos[idString] = {
									"? "..emoteName,
									id
								}
							end
						end
	
					else
	
						local idString = tostring(ids)
	
						if not favoritos[idString] then
							favoritos[idString] = {
								"? "..emoteName,
								ids
							}
						end
					end
				end
	
				salvarFavoritos()
			end
		end
	
		pesquisarCatalogo(search.Text)
	end
	
	-- FAVORITOS / GLOBAL
	favButton.MouseButton1Click:Connect(function()
	
		mostrandoFavoritos = not mostrandoFavoritos
	
		if mostrandoFavoritos then
			favButton.Text = "?"
		else
			favButton.Text = "??"
		end
	
		pesquisarCatalogo(search.Text)
	end)
	
	-- SEARCH UPDATE
	local debounce = false
	
	search:GetPropertyChangedSignal("Text"):Connect(function()
	
		if debounce then
			return
		end
	
		debounce = true
	
		task.wait(0.4)
	
		pesquisarCatalogo(search.Text)
	
		debounce = false
	end)
	
	-- OPEN PANEL
	button.MouseButton1Click:Connect(function()
	
		emoteBox.Visible = not emoteBox.Visible
	
		if emoteBox.Visible then
			pesquisarCatalogo(search.Text)
		end
	end)
	
	-- HOTKEY CHANGE
	keyButton.MouseButton1Click:Connect(function()
	
		keyButton.Text = "..."
		escolhendoTecla = true
	end)
	
	-- HOTKEY INPUT
	UIS.InputBegan:Connect(function(input,gp)
	
		if gp then
			return
		end
	
		if escolhendoTecla and input.KeyCode ~= Enum.KeyCode.Unknown then
	
			hotkey = input.KeyCode
			keyButton.Text = input.KeyCode.Name
			escolhendoTecla = false
			return
		end
	
		if input.KeyCode == hotkey then
	
			emoteBox.Visible = not emoteBox.Visible
	
			if emoteBox.Visible then
				pesquisarCatalogo(search.Text)
			end
		end
	end)
	
	-- DRAG
	local dragging = false
	local dragInput
	local dragStart
	local startPos
	
	local function update(input)
	
		local delta = input.Position - dragStart
	
		emoteBox.Position = UDim2.new(
			startPos.X.Scale,
			startPos.X.Offset + delta.X,
			startPos.Y.Scale,
			startPos.Y.Offset + delta.Y
		)
	end
	
	topBar.InputBegan:Connect(function(input)
	
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
	
			dragging = true
			dragStart = input.Position
			startPos = emoteBox.Position
	
			input.Changed:Connect(function()
	
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)
	
	topBar.InputChanged:Connect(function(input)
	
		if input.UserInputType == Enum.UserInputType.MouseMovement then
			dragInput = input
		end
	end)
	
	UIS.InputChanged:Connect(function(input)
	
		if input == dragInput and dragging then
			update(input)
		end
	end)
	
	task.spawn(carregarEmotesDoPlayer)
end
local function BWWAVSL_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.clicktpButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_clicktpButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	
	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	
	local player = Players.LocalPlayer
	local playerGui = player:WaitForChild("PlayerGui")
	local mouse = player:GetMouse()
	
	---------------------------------------------------
	-- SISTEMA GLOBAL DE ATALHOS
	---------------------------------------------------
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	
	local OWNER = "ClickTP"
	
	---------------------------------------------------
	-- REFER�NCIAS
	---------------------------------------------------
	
	local clickTpButton = script.Parent
	local moviFrame = clickTpButton.Parent
	
	local mainFrame =
		clickTpButton:FindFirstAncestor("mainFrame")
	
	local atalhoButton =
		moviFrame:FindFirstChild("atalhotpButton")
		or clickTpButton:FindFirstChild("keybutton")
		or clickTpButton:FindFirstChild("key")
		or clickTpButton:FindFirstChild("tecla")
	
	---------------------------------------------------
	-- VARI�VEIS
	---------------------------------------------------
	
	local clickTpAtivado = false
	local escolhendoTecla = false
	local teclaAtalho = nil
	local atualizandoTextoTecla = false
	local avisoNumero = 0
	
	---------------------------------------------------
	-- CORES
	---------------------------------------------------
	
	local corOriginal = clickTpButton.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	
	---------------------------------------------------
	-- ATUALIZAR BOT�O
	---------------------------------------------------
	
	local function atualizarBotao()
	
		if clickTpAtivado then
			clickTpButton.BackgroundColor3 = corAtiva
		else
			clickTpButton.BackgroundColor3 = corOriginal
		end
	
	end
	
	---------------------------------------------------
	-- ATUALIZAR TEXTO DA TECLA
	---------------------------------------------------
	
	local function atualizarAtalho()
	
		if not atalhoButton then
			return
		end
	
		atualizandoTextoTecla = true
	
		atalhoButton.Text =
			teclaAtalho and teclaAtalho.Name or "-"
	
		atualizandoTextoTecla = false
	
	end
	
	---------------------------------------------------
	-- VALIDAR TECLA
	---------------------------------------------------
	
	local function obterTeclaDoTexto(texto)
	
		if type(texto) ~= "string" then
			return nil
		end
	
		local nome = string.upper(texto)
	
		if #nome ~= 1 then
			return nil
		end
	
		local codigo = string.byte(nome)
	
		if not (
			(codigo >= 48 and codigo <= 57)
				or (codigo >= 65 and codigo <= 90)
			) then
			return nil
		end
	
		return Enum.KeyCode[nome]
	
	end
	
	---------------------------------------------------
	-- MOSTRAR TECLA USADA
	---------------------------------------------------
	
	local function mostrarTeclaUsada()
	
		if not atalhoButton then
			return
		end
	
		avisoNumero += 1
		local avisoAtual = avisoNumero
	
		atualizandoTextoTecla = true
		atalhoButton.Text = "USADA"
		atualizandoTextoTecla = false
	
		task.delay(1.2, function()
	
			if avisoAtual ~= avisoNumero then
				return
			end
	
			if not atalhoButton.Parent then
				return
			end
	
			atualizarAtalho()
	
		end)
	
	end
	
	---------------------------------------------------
	-- DEFINIR TECLA
	---------------------------------------------------
	
	local function definirTecla(keyCode)
	
		if not keyCode
			or keyCode == Enum.KeyCode.Unknown then
			return false
		end
	
		local nome = keyCode.Name
	
		---------------------------------------------------
		-- APENAS A-Z E 0-9
		---------------------------------------------------
	
		if obterTeclaDoTexto(nome) ~= keyCode then
			return false
		end
	
		---------------------------------------------------
		-- VERIFICAR TECLA OCUPADA
		---------------------------------------------------
	
		local dono = _G.HPX_Atalhos[nome]
	
		if dono and dono ~= OWNER then
	
			escolhendoTecla = false
			mostrarTeclaUsada()
	
			return false
		end
	
		---------------------------------------------------
		-- REMOVER TECLA ANTIGA
		---------------------------------------------------
	
		if teclaAtalho then
	
			local nomeAntigo = teclaAtalho.Name
	
			if _G.HPX_Atalhos[nomeAntigo] == OWNER then
	
				_G.HPX_Atalhos[nomeAntigo] = nil
	
			end
	
		end
	
		---------------------------------------------------
		-- REGISTRAR NOVA TECLA
		---------------------------------------------------
	
		teclaAtalho = keyCode
		_G.HPX_Atalhos[nome] = OWNER
	
		escolhendoTecla = false
		avisoNumero += 1
	
		atualizarAtalho()
	
		if atalhoButton
			and atalhoButton:IsA("TextBox")
			and atalhoButton:IsFocused() then
	
			atalhoButton:ReleaseFocus()
	
		end
	
		return true
	
	end
	
	---------------------------------------------------
	-- ATIVAR / DESATIVAR CLICK TP
	---------------------------------------------------
	
	local function alternarClickTP()
	
		clickTpAtivado = not clickTpAtivado
	
		atualizarBotao()
	
	end
	
	---------------------------------------------------
	-- BOT�O CLICK TP
	---------------------------------------------------
	
	clickTpButton.MouseButton1Click:Connect(function()
	
		alternarClickTP()
	
	end)
	
	---------------------------------------------------
	-- CAMPO DE ATALHO
	---------------------------------------------------
	
	if atalhoButton then
	
		---------------------------------------------------
		-- TEXTBOX
		---------------------------------------------------
	
		if atalhoButton:IsA("TextBox") then
	
			atalhoButton.TextEditable = true
			atalhoButton.ClearTextOnFocus = false
	
			atalhoButton:GetPropertyChangedSignal("Text"):Connect(function()
	
				if atualizandoTextoTecla then
					return
				end
	
				local texto = atalhoButton.Text or ""
	
				local primeiroCaractere =
					string.upper(texto:sub(1, 1))
	
				local tecla =
					obterTeclaDoTexto(primeiroCaractere)
	
				atualizandoTextoTecla = true
	
				atalhoButton.Text =
					tecla and primeiroCaractere or ""
	
				atualizandoTextoTecla = false
	
				if tecla then
					definirTecla(tecla)
				end
	
			end)
	
			atalhoButton.FocusLost:Connect(function()
	
				if atalhoButton.Text ~= "USADA" then
					atualizarAtalho()
				end
	
			end)
	
			---------------------------------------------------
			-- TEXTBUTTON
			---------------------------------------------------
	
		elseif atalhoButton:IsA("TextButton") then
	
			atalhoButton.MouseButton1Click:Connect(function()
	
				escolhendoTecla = true
	
				atalhoButton.Text = "..."
	
			end)
	
		end
	
	end
	
	---------------------------------------------------
	-- SISTEMA DE TECLADO
	---------------------------------------------------
	
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
	
		if input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
	
		---------------------------------------------------
		-- ESCOLHER NOVA TECLA
		---------------------------------------------------
	
		if escolhendoTecla then
	
			if input.KeyCode == Enum.KeyCode.Escape then
	
				escolhendoTecla = false
				atualizarAtalho()
	
				return
			end
	
			local teclaNova =
				obterTeclaDoTexto(input.KeyCode.Name)
	
			if teclaNova then
				definirTecla(teclaNova)
			end
	
			return
		end
	
		---------------------------------------------------
		-- N�O ATIVAR ENQUANTO DIGITA
		---------------------------------------------------
	
		if gameProcessed then
			return
		end
	
		if UserInputService:GetFocusedTextBox() then
			return
		end
	
		---------------------------------------------------
		-- ATIVAR / DESATIVAR PELO ATALHO
		---------------------------------------------------
	
		if teclaAtalho
			and input.KeyCode == teclaAtalho
			and _G.HPX_Atalhos[teclaAtalho.Name] == OWNER then
	
			alternarClickTP()
	
		end
	
	end)
	
	---------------------------------------------------
	-- DETECTAR CLIQUES NA INTERFACE
	---------------------------------------------------
	
	local function clicouNaInterface()
	
		local posicao = UserInputService:GetMouseLocation()
	
		-- CORRIGIDO:
		-- GetGuiObjectsAtPosition pertence ao PlayerGui,
		-- n�o ao GuiService.
	
		local objetos = playerGui:GetGuiObjectsAtPosition(
			posicao.X,
			posicao.Y
		)
	
		for _, objeto in ipairs(objetos) do
	
			if objeto.Visible then
	
				---------------------------------------------------
				-- IGNORAR CLIQUES DENTRO DO PAINEL HPX
				---------------------------------------------------
	
				if mainFrame then
	
					if objeto == mainFrame
						or objeto:IsDescendantOf(mainFrame) then
	
						return true
	
					end
	
				end
	
				---------------------------------------------------
				-- IGNORAR CLIQUES NO CLICK TP
				---------------------------------------------------
	
				if objeto == clickTpButton
					or objeto:IsDescendantOf(clickTpButton) then
	
					return true
	
				end
	
				---------------------------------------------------
				-- IGNORAR OUTROS ELEMENTOS INTERATIVOS
				---------------------------------------------------
	
				if objeto:IsA("GuiButton")
					or objeto:IsA("TextBox")
					or objeto.Active then
	
					return true
	
				end
	
			end
	
		end
	
		return false
	
	end
	
	---------------------------------------------------
	-- CLICK TELEPORT ORIGINAL
	---------------------------------------------------
	
	mouse.Button1Down:Connect(function()
	
		if not clickTpAtivado then
			return
		end
	
		---------------------------------------------------
		-- IGNORAR DIGITA��O
		---------------------------------------------------
	
		if UserInputService:GetFocusedTextBox() then
			return
		end
	
		---------------------------------------------------
		-- N�O TELEPORTAR AO CLICAR NA GUI
		---------------------------------------------------
	
		if clicouNaInterface() then
			return
		end
	
		---------------------------------------------------
		-- PERSONAGEM
		---------------------------------------------------
	
		local character = player.Character
	
		if not character then
			return
		end
	
		local root =
			character:FindFirstChild("HumanoidRootPart")
	
		if not root then
			return
		end
	
		---------------------------------------------------
		-- POSI��O DO MOUSE
		---------------------------------------------------
	
		local hit = mouse.Hit
	
		if not hit then
			return
		end
	
		local pos = hit.Position
	
		---------------------------------------------------
		-- TELEPORTAR
		---------------------------------------------------
	
		root.CFrame = CFrame.new(
			pos.X,
			pos.Y + 3,
			pos.Z
		)
	
	end)
	
	---------------------------------------------------
	-- LIMPEZA
	---------------------------------------------------
	
	script.Destroying:Connect(function()
	
		if teclaAtalho
			and _G.HPX_Atalhos[teclaAtalho.Name] == OWNER then
	
			_G.HPX_Atalhos[teclaAtalho.Name] = nil
	
		end
	
	end)
	
	---------------------------------------------------
	-- INICIAR
	---------------------------------------------------
	
	atualizarBotao()
	atualizarAtalho()
	
end
