	-- Desligado, apenas os eventos do botao e do atalho ficam conectados.
	local UIS = game:GetService("UserInputService")
	local botao = script.Parent
	assert(botao and botao:IsA("GuiButton"), "Coloque este LocalScript dentro de FantasmaVerButton.")
	
	local anterior = _G.HPX_GhostBootstrap
	if type(anterior) == "table" and type(anterior.cancel) == "function" then anterior.cancel() end
	if type(_G.HPX_AzulStop) == "function" then pcall(_G.HPX_AzulStop) end
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	local registros = _G.HPX_Atalhos
	local NOME = "VerFantasma"
	local corOriginal = botao.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	local keybutton = botao:FindFirstChild("keybutton") or botao:FindFirstChild("atalhoButton")
		or botao:FindFirstChild("key") or botao:FindFirstChild("tecla")
	if keybutton and not (keybutton:IsA("TextBox") or keybutton:IsA("TextButton") or keybutton:IsA("TextLabel")) then
		keybutton = keybutton:FindFirstChildWhichIsA("TextBox", true)
			or keybutton:FindFirstChildWhichIsA("TextButton", true)
			or keybutton:FindFirstChildWhichIsA("TextLabel", true)
	end
	local startup = { enabled = false, vivo = true, conexoes = {} }
	_G.HPX_GhostBootstrap = startup
	local teclaAtual, escolhendo, editandoTexto, keyPress = nil, false, false, false
	local suppressedKey
	local digitos = { Zero = "0", One = "1", Two = "2", Three = "3", Four = "4",
		Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9" }
	local aviso = 0
	local function ligar(sinal, fn)
		local c = sinal:Connect(fn)
		table.insert(startup.conexoes, c)
		return c
	end
	local function atualizarBotao()
		if not botao.Parent then return end
		botao.BackgroundColor3 = startup.enabled and corAtiva or corOriginal
		botao:SetAttribute("HPXGhostEnabled", startup.enabled)
	end
	local function textoTecla(texto)
		if not keybutton or not keybutton.Parent then return end
		editandoTexto = true
		keybutton.Text = texto
		editandoTexto = false
	end
	local function atualizarTecla()
		textoTecla(teclaAtual and (digitos[teclaAtual.Name] or teclaAtual.Name) or "-")
	end
	local function teclaValida(tecla)
		return tecla and tecla ~= Enum.KeyCode.Unknown
			and (tecla.Name:match("^[A-Z0-9]$") ~= nil or digitos[tecla.Name] ~= nil)
	end
	local function confirmar(tecla)
		if not teclaValida(tecla) then return end
		local nome = tecla.Name
		if registros[nome] and registros[nome] ~= NOME then
			aviso = aviso + 1
			local atual = aviso
			textoTecla("USADA")
			task.delay(1.2, function()
				if startup.vivo and aviso == atual then atualizarTecla() end
			end)
			return
		end
		if teclaAtual and registros[teclaAtual.Name] == NOME then registros[teclaAtual.Name] = nil end
		teclaAtual = tecla
		suppressedKey = tecla
		registros[nome] = NOME
		escolhendo = false
		aviso = aviso + 1
		atualizarTecla()
		if keybutton and keybutton:IsA("TextBox") and keybutton:IsFocused() then keybutton:ReleaseFocus() end
	end
	function startup.setEnabled(value)
		if not startup.vivo then return end
		local enabled = value == true
		if enabled == startup.enabled then return end
		startup.enabled = enabled
		if enabled then
			local ok, controller = pcall(iniciarFantasma, startup)
			if ok and controller then
				controller.Abrir()
			else
				startup.enabled = false
				if startup.controller then startup.controller.Destroy() end
			end
		elseif startup.controller then
			startup.controller.Destroy()
		end
		atualizarBotao()
	end
	function startup.cancel()
		if not startup.vivo then return end
		startup.vivo = false
		startup.enabled = false
		if startup.controller then startup.controller.Destroy() end
		if teclaAtual and registros[teclaAtual.Name] == NOME then registros[teclaAtual.Name] = nil end
		for _, c in ipairs(startup.conexoes) do c:Disconnect() end
		table.clear(startup.conexoes)
		atualizarBotao()
		if _G.HPX_GhostBootstrap == startup then _G.HPX_GhostBootstrap = nil end
	end
	ligar(botao.Activated, function()
		if not escolhendo and not keyPress then startup.setEnabled(not startup.enabled) end
	end)
	if keybutton then
		ligar(keybutton.InputBegan, function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				keyPress = true
			end
		end)
		if keybutton:IsA("TextBox") then
			keybutton.ClearTextOnFocus = false
			ligar(keybutton.Focused, function() escolhendo = true; textoTecla("") end)
			ligar(keybutton:GetPropertyChangedSignal("Text"), function()
				if editandoTexto or not escolhendo then return end
				local letra = keybutton.Text:upper():match("[A-Z0-9]")
				if not letra then return end
				for nome, digito in pairs(digitos) do
					if digito == letra then confirmar(Enum.KeyCode[nome]); return end
				end
				confirmar(Enum.KeyCode[letra])
			end)
			ligar(keybutton.FocusLost, function() escolhendo = false; atualizarTecla() end)
		elseif keybutton:IsA("TextButton") then
			ligar(keybutton.Activated, function() escolhendo = true; textoTecla("...") end)
		end
	end
	ligar(UIS.InputBegan, function(input, processado)
		if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		if escolhendo then
			if input.KeyCode == Enum.KeyCode.Escape then escolhendo = false; atualizarTecla()
			else confirmar(input.KeyCode) end
			return
		end
		if processado or UIS:GetFocusedTextBox() or input.KeyCode == suppressedKey then return end
		if teclaAtual and input.KeyCode == teclaAtual and registros[teclaAtual.Name] == NOME then
			startup.setEnabled(not startup.enabled)
		end
	end)
	ligar(UIS.InputEnded, function(input)
		if input.KeyCode == suppressedKey then suppressedKey = nil end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			task.defer(function() if startup.vivo then keyPress = false end end)
		end
	end)
	ligar(botao:GetAttributeChangedSignal("HPXGhostEnabled"), function()
		startup.setEnabled(botao:GetAttribute("HPXGhostEnabled") == true)
	end)
	ligar(script.Destroying, startup.cancel)
	ligar(botao.Destroying, startup.cancel)
	atualizarTecla()
	atualizarBotao()
	
end
local function CVEJW_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.EspButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_EspButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	-- ESP + Atalho sem tecla repetida
	-- Coloque este LocalScript dentro do EspButton
	
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")
	
	local player = Players.LocalPlayer
	local camera = workspace.CurrentCamera
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	
	---------------------------------------------------
	-- REFER�NCIAS
	---------------------------------------------------
	
	local espButton = script.Parent
	local movi = espButton.Parent
	local bindButton = espButton:FindFirstChild("keybutton")
		or espButton:FindFirstChild("key")
		or espButton:FindFirstChild("tecla")
		or movi:FindFirstChild("BindButton")
	
	---------------------------------------------------
	-- VARI�VEIS
	---------------------------------------------------
	
	local espAtivo = false
	local teclaAtual = nil
	local escolhendoTecla = false
	local atualizandoTextoTecla = false
	
	local gui
	local markers = {}
	local renderConnection
	
	---------------------------------------------------
	-- CONFIGURA��ES
	---------------------------------------------------
	
	local MARKER_SIZE = 24
	local ALTURA_ACIMA_DA_CABECA = 1.1
	
	local DISTANCIA_TRANSPARENTE = 8
	local DISTANCIA_MAXIMA = 120
	
	---------------------------------------------------
	-- COR ORIGINAL DO BOT�O
	---------------------------------------------------
	
	local corOriginal = espButton.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	
	---------------------------------------------------
	-- BOT�ES
	---------------------------------------------------
	
	local function atualizarBotoes()
	
		-- N�o altera mais o texto do bot�o,
		-- porque voc� j� tem um Label com o nome.
	
		if espAtivo then
			espButton.BackgroundColor3 = corAtiva
		else
			espButton.BackgroundColor3 = corOriginal
		end
	
		if bindButton and (bindButton:IsA("TextButton") or bindButton:IsA("TextLabel")) then
			if teclaAtual then
				bindButton.Text = teclaAtual.Name
			else
				bindButton.Text = "-"
			end
	
		elseif bindButton and bindButton:IsA("TextBox") then
			if teclaAtual then
				atualizandoTextoTecla = true
				bindButton.Text = teclaAtual.Name
				atualizandoTextoTecla = false
			else
				atualizandoTextoTecla = true
				bindButton.Text = "-"
				atualizandoTextoTecla = false
			end
		end
	end
	
	local function obterTeclaDoTexto(texto)
		if type(texto) ~= "string" or texto == "" then
			return nil
		end
	
		local letra = string.upper(texto:sub(1, 1))
	
		if #letra ~= 1 then
			return nil
		end
	
		local codigo = string.byte(letra)
	
		if (codigo >= 48 and codigo <= 57)
			or (codigo >= 65 and codigo <= 90) then
	
			return Enum.KeyCode[letra]
		end
	
		return nil
	end
	
	local function confirmarTecla(keyCode)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then return false end
		local nome = keyCode.Name
		if not nome:match("^[A-Z0-9]$") then return false end
	
		local dono = _G.HPX_Atalhos[nome]
		if dono and dono ~= "ESP" then
			escolhendoTecla = false
			if bindButton and bindButton:IsA("TextBox") and bindButton:IsFocused() then
				bindButton:ReleaseFocus()
			end
			if bindButton then
				atualizandoTextoTecla = true
				bindButton.Text = "USADA"
				atualizandoTextoTecla = false
			end
			task.delay(1.2, function()
				if espButton.Parent then atualizarBotoes() end
			end)
			return false
		end
	
		if teclaAtual and _G.HPX_Atalhos[teclaAtual.Name] == "ESP" then
			_G.HPX_Atalhos[teclaAtual.Name] = nil
		end
		teclaAtual = keyCode
		_G.HPX_Atalhos[nome] = "ESP"
		escolhendoTecla = false
		atualizarBotoes()
	
		-- Solta o campo imediatamente: o proximo Z liga o ESP.
		if bindButton and bindButton:IsA("TextBox") and bindButton:IsFocused() then
			bindButton:ReleaseFocus()
		end
		return true
	end
	
	---------------------------------------------------
	-- CRIAR MARKER
	---------------------------------------------------
	
	local function criarMarker(p)
	
		if p == player then
			return
		end
	
		if markers[p] then
			return
		end
	
		if not gui then
			return
		end
	
		local btn = Instance.new("ImageButton")
	
		btn.Name = "ESP_" .. p.Name
	
		btn.Size = UDim2.new(
			0,
			MARKER_SIZE,
			0,
			MARKER_SIZE
		)
	
		btn.AnchorPoint = Vector2.new(0.5, 0.5)
	
		btn.BackgroundColor3 = Color3.fromRGB(47, 47, 71)
		btn.BorderSizePixel = 0
	
		btn.Visible = false
	
		btn.Parent = gui
	
		local corner = Instance.new("UICorner")
	
		corner.CornerRadius = UDim.new(1, 0)
		corner.Parent = btn
	
		local stroke = Instance.new("UIStroke")
	
		stroke.Thickness = 2
		stroke.Color = Color3.fromRGB(164, 164, 188)
		stroke.Parent = btn
	
		btn.Image =
			"https://www.roblox.com/headshot-thumbnail/image?userId="
			.. p.UserId
			.. "&width=420&height=420&format=png"
	
		markers[p] = btn
	
		btn.MouseButton1Click:Connect(function()
	
			local myChar = player.Character
			local target = p.Character
	
			if myChar
				and target
				and target:FindFirstChild("HumanoidRootPart") then
	
				myChar:PivotTo(
					target.HumanoidRootPart.CFrame
						+ Vector3.new(2, 0, 0)
				)
			end
		end)
	end
	
	---------------------------------------------------
	-- PEGAR POSI��O ACIMA DA CABE�A
	---------------------------------------------------
	
	local function getPosicaoAcimaDaCabeca(char)
	
		local head = char:FindFirstChild("Head")
	
		if head then
			return head.Position
				+ Vector3.new(
					0,
					ALTURA_ACIMA_DA_CABECA,
					0
				)
		end
	
		local cf, size = char:GetBoundingBox()
	
		return cf.Position
			+ Vector3.new(
				0,
				size.Y / 2 + 0.7,
				0
			)
	end
	
	---------------------------------------------------
	-- LIGAR ESP
	---------------------------------------------------
	
	local function ligarESP()
	
		if gui then
			return
		end
	
		gui = Instance.new("ScreenGui")
	
		gui.Name = "ESP_Gui"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
	
		gui.Parent = player:WaitForChild("PlayerGui")
	
		for _, p in pairs(Players:GetPlayers()) do
			criarMarker(p)
		end
	
		renderConnection = RunService.RenderStepped:Connect(function()
	
			camera = workspace.CurrentCamera
	
			local myChar = player.Character
			local myRoot =
				myChar
				and myChar:FindFirstChild("HumanoidRootPart")
	
			for p, btn in pairs(markers) do
	
				local char = p.Character
				local root =
					char
					and char:FindFirstChild("HumanoidRootPart")
	
				if char and root and myRoot then
	
					local worldPos =
						getPosicaoAcimaDaCabeca(char)
	
					local screenPos, onScreen =
						camera:WorldToViewportPoint(worldPos)
	
					if onScreen and screenPos.Z > 0 then
	
						btn.Visible = true
	
						btn.Position =
							UDim2.fromOffset(
								screenPos.X,
								screenPos.Y
							)
	
						local dist =
							(
								myRoot.Position
								- root.Position
							).Magnitude
	
						local transparencia
	
						if dist <= DISTANCIA_TRANSPARENTE then
	
							transparencia = 0.92
	
						else
	
							transparencia =
								math.clamp(
									1
									- (
										dist
										/ DISTANCIA_MAXIMA
									),
									0.15,
									0.92
								)
						end
	
						btn.ImageTransparency =
							transparencia
	
						btn.BackgroundTransparency =
							transparencia
	
						local stroke =
							btn:FindFirstChildOfClass("UIStroke")
	
						if stroke then
							stroke.Transparency =
								transparencia
						end
	
					else
	
						btn.Visible = false
					end
	
				else
	
					btn.Visible = false
				end
			end
		end)
	end
	
	---------------------------------------------------
	-- DESLIGAR ESP
	---------------------------------------------------
	
	local function desligarESP()
	
		if renderConnection then
			renderConnection:Disconnect()
			renderConnection = nil
		end
	
		for _, btn in pairs(markers) do
			btn:Destroy()
		end
	
		markers = {}
	
		if gui then
			gui:Destroy()
			gui = nil
		end
	end
	
	---------------------------------------------------
	-- TOGGLE ESP
	---------------------------------------------------
	
	local function toggleESP()
	
		espAtivo = not espAtivo
	
		if espAtivo then
			ligarESP()
		else
			desligarESP()
		end
	
		atualizarBotoes()
	end
	
	---------------------------------------------------
	-- BOT�O ESP
	---------------------------------------------------
	
	espButton.MouseButton1Click:Connect(function()
	
		toggleESP()
	
	end)
	
	---------------------------------------------------
	-- BOT�O ATALHO - IGUAL AO BOT�O CORRER
	---------------------------------------------------
	
	if bindButton and bindButton:IsA("TextBox") then
		bindButton.ClearTextOnFocus = false
		bindButton.TextEditable = true
	
		bindButton.Focused:Connect(function()
			escolhendoTecla = true
			atualizandoTextoTecla = true
			bindButton.Text = ""
			atualizandoTextoTecla = false
		end)
	
		bindButton:GetPropertyChangedSignal("Text"):Connect(function()
			if atualizandoTextoTecla then return end
			local letra = (bindButton.Text or ""):upper():sub(1,1)
			local novaTecla = obterTeclaDoTexto(letra)
			atualizandoTextoTecla = true
			bindButton.Text = novaTecla and letra or ""
			atualizandoTextoTecla = false
			if novaTecla then confirmarTecla(novaTecla) end
		end)
	
		bindButton.FocusLost:Connect(function()
			escolhendoTecla = false
			-- Evita apagar USADA antes da mensagem terminar
			if bindButton.Text ~= "USADA" then atualizarBotoes() end
		end)
	
	elseif bindButton and bindButton:IsA("TextButton") then
		bindButton.MouseButton1Click:Connect(function()
			escolhendoTecla = true
			bindButton.Text = "..."
		end)
	end
	
	---------------------------------------------------
	-- TECLADO
	---------------------------------------------------
	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
	
		-- Sele��o por TextButton (TextBox usa mudan�a de Text acima)
		if escolhendoTecla and bindButton and not bindButton:IsA("TextBox") then
			if input.KeyCode == Enum.KeyCode.Escape then
				escolhendoTecla = false
				atualizarBotoes()
			elseif obterTeclaDoTexto(input.KeyCode.Name) then
				confirmarTecla(input.KeyCode)
			end
			return
		end
	
		if gameProcessed or UserInputService:GetFocusedTextBox() then return end
		if teclaAtual and input.KeyCode == teclaAtual
			and _G.HPX_Atalhos[teclaAtual.Name] == "ESP" then
			toggleESP()
		end
	end)
	
	---------------------------------------------------
	-- PLAYER ENTROU
	---------------------------------------------------
	
	Players.PlayerAdded:Connect(function(p)
	
		if espAtivo then
			criarMarker(p)
		end
	end)
	
	---------------------------------------------------
	-- PLAYER SAIU
	---------------------------------------------------
	
	Players.PlayerRemoving:Connect(function(p)
	
		if markers[p] then
	
			markers[p]:Destroy()
			markers[p] = nil
	
		end
	end)
	
	---------------------------------------------------
	-- INICIAR
	---------------------------------------------------
	
	atualizarBotoes()
end
local function AUIH_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.antiflingButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_antiflingButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	local RunService = game:GetService("RunService")
	
	local player = Players.LocalPlayer
	local antiFlingButton = script.Parent
	local mainFrame = antiFlingButton:FindFirstAncestor("mainFrame")
	local flyState
	
	---------------------------------------------------
	-- SISTEMA GLOBAL DE ATALHOS
	---------------------------------------------------
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	
	local OWNER = "AntiFling"
	
	---------------------------------------------------
	-- FLY STATE
	---------------------------------------------------
	
	if mainFrame then
		local stalkerFrame = mainFrame:FindFirstChild("stalker")
		local cmdsFolder = stalkerFrame and stalkerFrame:FindFirstChild("Cmds", true)
	
		if cmdsFolder then
			flyState = cmdsFolder:FindFirstChild("FlyAtivo")
	
			if not flyState then
				flyState = Instance.new("BoolValue")
				flyState.Name = "FlyAtivo"
				flyState.Parent = cmdsFolder
			end
		end
	end
	
	---------------------------------------------------
	-- REFER�NCIAS
	---------------------------------------------------
	
	local keyButton =
		antiFlingButton:FindFirstChild("keybutton")
		or antiFlingButton:FindFirstChild("key")
	
	---------------------------------------------------
	-- CORES
	---------------------------------------------------
	
	local corOriginal = antiFlingButton.BackgroundColor3
	local corAtiva = Color3.fromRGB(0, 170, 0)
	
	---------------------------------------------------
	-- VARI�VEIS
	---------------------------------------------------
	
	local antiFlingAtivo = false
	local antiFlingConnection
	
	local teclaAtual
	local atualizandoTextoTecla = false
	
	local partesColisaoOriginal = {}
	
	---------------------------------------------------
	-- TEXTO DA TECLA
	---------------------------------------------------
	
	local function atualizarTextoTecla()
		if not keyButton then
			return
		end
	
		local texto =
			teclaAtual
			and teclaAtual.Name
			or ""
	
		if keyButton:IsA("TextBox") then
	
			atualizandoTextoTecla = true
			keyButton.Text = texto
			atualizandoTextoTecla = false
	
		elseif keyButton:IsA("TextButton")
			or keyButton:IsA("TextLabel") then
	
			keyButton.Text = texto
		end
	end
	
	---------------------------------------------------
	-- OBTER TECLA
	---------------------------------------------------
	
	local function obterTecla(text)
		local keyName =
			string.upper(
				(text or ""):sub(1, 1)
			)
	
		if #keyName ~= 1 then
			return nil
		end
	
		local charCode =
			string.byte(keyName)
	
		-- Somente A-Z e 0-9
		if not (
			(charCode >= 48 and charCode <= 57)
				or
				(charCode >= 65 and charCode <= 90)
			) then
	
			return nil
		end
	
		return Enum.KeyCode[keyName]
	end
	
	---------------------------------------------------
	-- DEFINIR TECLA
	---------------------------------------------------
	
	local function definirTecla(keyCode)
		if not keyCode
			or keyCode == Enum.KeyCode.Unknown then
	
			return
		end
	
		local nome = keyCode.Name
		local dono = _G.HPX_Atalhos[nome]
	
		---------------------------------------------------
		-- TECLA J� USADA
		---------------------------------------------------
	
		if dono and dono ~= OWNER then
	
			if keyButton then
	
				atualizandoTextoTecla = true
				keyButton.Text = "USADA"
				atualizandoTextoTecla = false
	
			end
	
			task.delay(1.2, function()
				atualizarTextoTecla()
			end)
	
			return
		end
	
		---------------------------------------------------
		-- LIBERA TECLA ANTIGA
		---------------------------------------------------
	
		if teclaAtual
			and _G.HPX_Atalhos[teclaAtual.Name] == OWNER then
	
			_G.HPX_Atalhos[teclaAtual.Name] = nil
		end
	
		---------------------------------------------------
		-- SALVA NOVA TECLA
		---------------------------------------------------
	
		teclaAtual = keyCode
		_G.HPX_Atalhos[nome] = OWNER
	
		atualizarTextoTecla()
	
		if keyButton
			and keyButton:IsA("TextBox")
			and keyButton:IsFocused() then
	
			keyButton:ReleaseFocus()
		end
	end
	
	---------------------------------------------------
	-- COR DO BOT�O
	---------------------------------------------------
	
	local function atualizarBotao()
	
		if antiFlingAtivo then
	
			antiFlingButton.BackgroundColor3 =
				corAtiva
	
		else
	
			antiFlingButton.BackgroundColor3 =
				corOriginal
	
		end
	end
	
	---------------------------------------------------
	-- DESLIGAR COLIS�O
	---------------------------------------------------
	
	local function desligarColisaoDoPersonagem()
	
		local character = player.Character
	
		if not character then
			return
		end
	
		partesColisaoOriginal = {}
	
		for _, part in ipairs(
			character:GetDescendants()
			) do
	
			if part:IsA("BasePart") then
	
				partesColisaoOriginal[part] =
					part.CanCollide
	
				part.CanCollide = false
			end
		end
	end
	
	---------------------------------------------------
	-- RESTAURAR COLIS�O
	---------------------------------------------------
	
	local function restaurarColisaoDoPersonagem()
	
		for part, valor
			in pairs(partesColisaoOriginal) do
	
			if part and part.Parent then
				part.CanCollide = valor
			end
		end
	
		partesColisaoOriginal = {}
	end
	
	---------------------------------------------------
	-- DESLIGAR ANTI FLING
	---------------------------------------------------
	
	local function desligarAntiFling()
	
		if antiFlingConnection then
			antiFlingConnection:Disconnect()
			antiFlingConnection = nil
		end
	
		antiFlingAtivo = false
	
		restaurarColisaoDoPersonagem()
	
		atualizarBotao()
	end
	
	---------------------------------------------------
	-- LIGAR ANTI FLING
	---------------------------------------------------
	
	local function ligarAntiFling()
	
		if flyState
			and flyState.Value then
	
			return
		end
	
		local character =
			player.Character
	
		if not character then
			return
		end
	
		antiFlingAtivo = true
	
		desligarColisaoDoPersonagem()
	
		atualizarBotao()
	
		antiFlingConnection =
			RunService.RenderStepped:Connect(function()
	
				if not antiFlingAtivo
					or not player.Character then
	
					return
				end
	
				for _, part in ipairs(
					player.Character:GetDescendants()
					) do
	
					if part:IsA("BasePart") then
						part.CanCollide = false
					end
				end
			end)
	end
	
	---------------------------------------------------
	-- ALTERNAR
	---------------------------------------------------
	
	local function alternarAntiFling()
	
		if antiFlingAtivo then
			desligarAntiFling()
		else
			ligarAntiFling()
		end
	end
	
	---------------------------------------------------
	-- FLY
	---------------------------------------------------
	
	if flyState then
	
		flyState:GetPropertyChangedSignal("Value"):Connect(function()
	
			if flyState.Value
				and antiFlingAtivo then
	
				desligarAntiFling()
			end
		end)
	end
	
	---------------------------------------------------
	-- CAMPO DA TECLA
	---------------------------------------------------
	
	if keyButton
		and keyButton:IsA("TextBox") then
	
		keyButton.TextEditable = true
		keyButton.ClearTextOnFocus = false
	
		keyButton:GetPropertyChangedSignal("Text"):Connect(function()
	
			if atualizandoTextoTecla then
				return
			end
	
			local texto =
				string.upper(
					keyButton.Text or ""
				)
	
			-- SOMENTE 1 CARACTERE
			local primeiroCaractere =
				texto:sub(1, 1)
	
			local tecla =
				obterTecla(
					primeiroCaractere
				)
	
			local textoValido =
				tecla
				and primeiroCaractere
				or ""
	
			atualizandoTextoTecla = true
	
			keyButton.Text =
				textoValido
	
			atualizandoTextoTecla = false
	
			if tecla then
				definirTecla(tecla)
			end
		end)
	
		keyButton.FocusLost:Connect(function()
			atualizarTextoTecla()
		end)
	end
	
	---------------------------------------------------
	-- BOT�O ANTI FLING
	---------------------------------------------------
	
	if antiFlingButton:IsA("TextButton") then
	
		antiFlingButton.MouseButton1Click:Connect(
			alternarAntiFling
		)
	
	else
	
		antiFlingButton.Activated:Connect(
			alternarAntiFling
		)
	
	end
	
	---------------------------------------------------
	-- ATALHO
	---------------------------------------------------
	
	UserInputService.InputBegan:Connect(function(
		input,
		gameProcessed
	)
	
		if gameProcessed then
			return
		end
	
		-- N�o ativa o AntiFling enquanto estiver
		-- digitando no campo da tecla
		if keyButton
			and keyButton:IsA("TextBox")
			and keyButton:IsFocused() then
	
			return
		end
	
		if teclaAtual
			and input.UserInputType
			== Enum.UserInputType.Keyboard
			and input.KeyCode
			== teclaAtual then
	
			alternarAntiFling()
		end
	end)
	
	---------------------------------------------------
	-- RESPAWN
	---------------------------------------------------
	
	player.CharacterAdded:Connect(function()
	
		if antiFlingAtivo then
	
			desligarAntiFling()
	
			task.wait()
	
			ligarAntiFling()
		end
	end)
	
	---------------------------------------------------
	-- LIMPEZA
	---------------------------------------------------
	
	script.Destroying:Connect(function()
	
		if teclaAtual
			and _G.HPX_Atalhos[teclaAtual.Name] == OWNER then
	
			_G.HPX_Atalhos[teclaAtual.Name] = nil
		end
	
		if antiFlingConnection then
			antiFlingConnection:Disconnect()
			antiFlingConnection = nil
		end
	end)
	
	---------------------------------------------------
	-- INICIAR
	---------------------------------------------------
	
	atualizarTextoTecla()
	atualizarBotao()
end
local function SFSGIWG_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.movi.ScrollingFrame.RunButton.LocalScript
    local script = Instance.new("LocalScript")
    script.Name = "LocalScript"
    script.Parent = Converted["_RunButton"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	-- HPX CORRER | Interface 100% Scale | LocalScript dentro de RunButton
	-- Mantem FlyAtivo, atalho exclusivo, speedBox e slider.
	local Players = game:GetService('Players')
	local UIS = game:GetService('UserInputService')
	local player = Players.LocalPlayer
	local runButton = script.Parent
	assert(runButton:IsA('GuiButton'), 'O script deve ficar dentro do RunButton (TextButton/ImageButton).')
	
	_G.HPX_Atalhos = _G.HPX_Atalhos or {}
	local OWNER = 'Correr'
	local MIN_SPEED, MAX_SPEED, DEFAULT_SPEED = -50, 500, 50
	local BASE_WALK_SPEED = 16
	local velocidade = DEFAULT_SPEED
	local correndo, teclaAtual, atualizandoTecla, arrastando = false, nil, false, false
	local corOriginal, corAtiva = runButton.BackgroundColor3, Color3.fromRGB(0,170,0)
	local conexoes = {}
	local function conectar(signal, fn)
		local c = signal:Connect(fn)
		table.insert(conexoes,c)
		return c
	end
	
	local mainFrame = runButton:FindFirstAncestor('mainFrame')
	local flyState
	if mainFrame then
		local stalker = mainFrame:FindFirstChild('stalker')
		local cmds = stalker and stalker:FindFirstChild('Cmds',true)
		if cmds then
			flyState = cmds:FindFirstChild('FlyAtivo')
			if not flyState then
				flyState = Instance.new('BoolValue')
				flyState.Name = 'FlyAtivo'
				flyState.Parent = cmds
			end
		end
	end
	
	-- Remove controles antigos criados por versoes anteriores para evitar sobreposicao.
	for _, obj in ipairs(runButton:GetChildren()) do
		if obj.Name == 'HPX_RunLayout' then obj:Destroy() end
	end
	for _, nome in ipairs({'speed','keybutton','key'}) do
		local antigo = runButton:FindFirstChild(nome)
		if antigo and antigo:IsA('GuiObject') then antigo.Visible = false end
	end
	runButton.Text = ''
	runButton.ClipsDescendants = true
	runButton.AutoButtonColor = false
	
	local function criar(classe, nome, parent, props)
		local obj = Instance.new(classe)
		obj.Name = nome
		for k,v in pairs(props) do obj[k]=v end
		obj.Parent = parent
		return obj
	end
	local function arredondar(obj, pixels)
		criar('UICorner','Corner',obj,{CornerRadius=UDim.new(0,pixels)})
	end
	local function textoResponsivo(obj, maxSize, minSize)
		obj.TextScaled = true
		criar('UITextSizeConstraint','TextLimit',obj,{MinTextSize=minSize,MaxTextSize=maxSize})
	end
	local layout = criar('Frame','HPX_RunLayout',runButton,{
		BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Position=UDim2.fromScale(0,0),
		ClipsDescendants=true,Active=false
	})
	local titulo = criar('TextLabel','Titulo',layout,{
		BackgroundTransparency=1,Position=UDim2.fromScale(.065,.095),Size=UDim2.fromScale(.61,.38),
		Text='Correr',Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Center
	})
	textoResponsivo(titulo,23,8)
	
	local keyBox = criar('TextBox','Atalho',layout,{
		Position=UDim2.fromScale(.755,.12),Size=UDim2.fromScale(.19,.39),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,
		Text='',PlaceholderText='-',PlaceholderColor3=Color3.fromRGB(220,225,235),Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		TextXAlignment=Enum.TextXAlignment.Center,ClearTextOnFocus=false,
		TextEditable=true,ZIndex=3
	})
	arredondar(keyBox,8)
	textoResponsivo(keyBox,17,7)
	
	local track = criar('Frame','Barra',layout,{
		Position=UDim2.fromScale(.075,.695),Size=UDim2.fromScale(.54,.125),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,Active=true,ZIndex=2
	})
	arredondar(track,100)
	local fill = criar('Frame','Preenchimento',track,{
		Position=UDim2.fromScale(0,0),Size=UDim2.fromScale(0,1),
		BackgroundColor3=Color3.fromRGB(0,170,255),BorderSizePixel=0,ZIndex=3
	})
	arredondar(fill,100)
	local knob = criar('Frame','Bolinha',track,{
		AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(0,.5),
		Size=UDim2.fromScale(.115,2.0),BackgroundColor3=Color3.fromRGB(245,247,255),
		BorderSizePixel=0,Active=true,ZIndex=4
	})
	criar('UIAspectRatioConstraint','Circular',knob,{AspectRatio=1,AspectType=Enum.AspectType.FitWithinMaxSize})
	arredondar(knob,100)
	
	local speedBox = criar('TextBox','Valor',layout,{
		Position=UDim2.fromScale(.675,.615),Size=UDim2.fromScale(.27,.285),
		BackgroundColor3=Color3.fromRGB(34,43,64),BorderSizePixel=0,
		Text='50',Font=Enum.Font.GothamBold,TextColor3=Color3.new(1,1,1),
		ClearTextOnFocus=false,TextXAlignment=Enum.TextXAlignment.Center,ZIndex=3
	})
	arredondar(speedBox,8)
	textoResponsivo(speedBox,16,7)
	
	local function humanoid()
		local char = player.Character
		local h = char and char:FindFirstChildOfClass('Humanoid')
		return h and h.Health > 0 and h or nil
	end
	local function walkSpeed()
		return math.max(0,(velocidade-MIN_SPEED)*BASE_WALK_SPEED/(DEFAULT_SPEED-MIN_SPEED))
	end
	local function atualizarVisual()
		runButton.BackgroundColor3 = correndo and corAtiva or corOriginal
	end
	local function atualizarBarra()
		local p = math.clamp((velocidade-MIN_SPEED)/(MAX_SPEED-MIN_SPEED),0,1)
		fill.Size = UDim2.fromScale(p,1)
		knob.Position = UDim2.fromScale(p,.5)
		if not speedBox:IsFocused() then speedBox.Text = tostring(velocidade) end
	end
	local function definirVelocidade(valor)
		if not valor then return end
		velocidade = math.clamp(math.floor(valor+.5),MIN_SPEED,MAX_SPEED)
		atualizarBarra()
		if correndo then
			local h = humanoid()
			if h then h.WalkSpeed = walkSpeed() end
		end
	end
	local function desligar()
		correndo=false
		local h=humanoid()
		if h then h.WalkSpeed=BASE_WALK_SPEED end
		atualizarVisual()
	end
	local function alternar()
		if correndo then desligar(); return end
		if flyState and flyState.Value then return end
		local h=humanoid()
		if not h then return end
		correndo=true
		h.WalkSpeed=walkSpeed()
		atualizarVisual()
	end
	
	local numbers = {'Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine'}
	local function codigo(texto)
		local ch=string.upper(tostring(texto or ''):sub(1,1))
		if ch:match('^[A-Z]$') then return Enum.KeyCode[ch] end
		if ch:match('^%d$') then return Enum.KeyCode[numbers[tonumber(ch)+1]] end
		return nil
	end
	local function exibicao(key)
		if not key then return '' end
		for i,n in ipairs(numbers) do if key.Name == n then return tostring(i-1) end end
		return key.Name
	end
	local function registro()
		if type(_G.HPX_Atalhos) ~= 'table' then _G.HPX_Atalhos = {} end
		return _G.HPX_Atalhos
	end
	-- O tracinho aparece apenas como PlaceholderText quando nao ha tecla.
	local function atualizarTecla()
		atualizandoTecla=true
		keyBox.Text=exibicao(teclaAtual)
		atualizandoTecla=false
	end
	local avisoId=0
	local function definirTecla(key)
		if not key then return end
		local reg=registro()
		local nome=exibicao(key)
		local dono=reg[nome] or reg[key.Name]
		if dono and dono~=OWNER then
			avisoId+=1
			local id=avisoId
			atualizandoTecla=true;keyBox.Text='USADA';atualizandoTecla=false
			task.delay(1.2,function() if id==avisoId and keyBox.Parent then atualizarTecla() end end)
			return
		end
		avisoId+=1
		if teclaAtual then
			local velho=exibicao(teclaAtual)
			if reg[velho]==OWNER then reg[velho]=nil end
			if reg[teclaAtual.Name]==OWNER then reg[teclaAtual.Name]=nil end
		end
		teclaAtual=key
		reg[nome]=OWNER
		atualizarTecla()
		if keyBox:IsFocused() then keyBox:ReleaseFocus() end
	end
	conectar(keyBox:GetPropertyChangedSignal('Text'),function()
		if atualizandoTecla or not keyBox:IsFocused() then return end
		local key=codigo(keyBox.Text)
		if key then definirTecla(key) end
	end)
	conectar(keyBox.FocusLost,atualizarTecla)
	conectar(speedBox.FocusLost,function()
		local value=tonumber(speedBox.Text)
		if value then definirVelocidade(value) else atualizarBarra() end
	end)
	
	local function ajustarPelaTela(x)
		if track.AbsoluteSize.X<=0 then return end
		local p=math.clamp((x-track.AbsolutePosition.X)/track.AbsoluteSize.X,0,1)
		definirVelocidade(MIN_SPEED+(MAX_SPEED-MIN_SPEED)*p)
	end
	for _,gui in ipairs({track,knob}) do
		conectar(gui.InputBegan,function(input)
			if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
				arrastando=true
				ajustarPelaTela(input.Position.X)
			end
		end)
	end
	conectar(UIS.InputChanged,function(input)
		if arrastando and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then
			ajustarPelaTela(input.Position.X)
		end
	end)
	conectar(UIS.InputEnded,function(input)
		if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
			arrastando=false
		end
	end)
	conectar(runButton.Activated,function()
		if arrastando or keyBox:IsFocused() or speedBox:IsFocused() then return end
		local mouse=UIS:GetMouseLocation()
		-- Nao alternar ao clicar nos campos ou na barra.
		local function dentro(obj)
			local p,s=obj.AbsolutePosition,obj.AbsoluteSize
			return mouse.X>=p.X and mouse.X<=p.X+s.X and mouse.Y>=p.Y and mouse.Y<=p.Y+s.Y
		end
		if dentro(track) or dentro(keyBox) or dentro(speedBox) then return end
		alternar()
	end)
	conectar(UIS.InputBegan,function(input,processed)
		if processed or UIS:GetFocusedTextBox() then return end
		if teclaAtual and input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode==teclaAtual then alternar() end
	end)
	if flyState then
		conectar(flyState:GetPropertyChangedSignal('Value'),function()
			if flyState.Value and correndo then desligar() end
		end)
	end
	conectar(player.CharacterAdded,function()
		if correndo then correndo=false;atualizarVisual() end
	end)
	conectar(script.Destroying,function()
		if correndo then desligar() end
		if teclaAtual then
			local reg=registro()
			if reg[exibicao(teclaAtual)]==OWNER then reg[exibicao(teclaAtual)]=nil end
			if reg[teclaAtual.Name]==OWNER then reg[teclaAtual.Name]=nil end
		end
		for _,c in ipairs(conexoes) do c:Disconnect() end
	end)
	
	atualizarBarra()
	atualizarTecla()
	atualizarVisual()
	print('[HPX CORRER] Scale pronto. Atalho e velocidade configuraveis.')
	
end
