	local function atualizarBarra()
		local p = math.clamp((velocidade-MIN_SPEED)/(MAX_SPEED-MIN_SPEED),0,1)
		fill.Size = UDim2.fromScale(p,1)
		knob.Position = UDim2.fromScale(p,.5)
		if not speedBox:IsFocused() then speedBox.Text = tostring(velocidade) end
	end
	local function definirVelocidade(valor)
		if not valor then return end
		velocidade = math.clamp(math.floor(valor+.5),MIN_SPEED,MAX_SPEED)
		atualizarBarra()
		if trackAnimacao and trackAnimacao.IsPlaying then
			trackAnimacao:AdjustSpeed(velocidadeAnimacao())
		end
	end
	local function desligar()
		girando=false
		if trackAnimacao then
			pcall(function() trackAnimacao:Stop(.12) end)
			trackAnimacao = nil
		end
		atualizarVisual()
	end
	local function iniciarAnimacao(h)
		local animator = h:FindFirstChildOfClass('Animator')
		if not animator then
			warn('[HPX GIRAR] Animator nao encontrado no Humanoid.')
			return nil
		end
		if CLIP_ANIMACAO_ID ~= '' then
			local anim = Instance.new('Animation')
			anim.AnimationId = CLIP_ANIMACAO_ID
			local ok, result = pcall(function() return animator:LoadAnimation(anim) end)
			anim:Destroy()
			if not ok then
				warn('[HPX GIRAR] Falha ao carregar clip:', result)
