	-- Remove duplicatas por proximidade (mantem a lista enxuta).
	do
		local unicos = {}
		for _, v in ipairs(coordenadas) do
			local pos = Vector3.new(v[1], v[2], v[3])
			local repetido = false
			for _, ja in ipairs(unicos) do
				if (ja - pos).Magnitude <= RAIO_MESMO_SPAWN then
					repetido = true
					break
				end
			end
			if not repetido then
				table.insert(unicos, pos)
			end
		end
		pontos = unicos
	end
	
	local ativo, rodando, vivo = false, false, true
	local monitorada, conexaoPasta = nil, nil
	
	local function logImportante(mensagem)
		local canal = playerGui:FindFirstChild("HPX_CandySpawnEvento")
		if canal and canal:IsA("BindableEvent") then
			canal:Fire(mensagem)
		end
	end
	
	-- ------------------------------------------------------------------
	-- Deteccao
	-- ------------------------------------------------------------------
	local function pastaCandy()
		return workspace:FindFirstChild(NOME_PASTA)
	end
	
	local function ehDoce(obj)
		return obj and obj.Name:lower() == NOME_DOCE
	end
	
	local function posicaoDoce(obj)
		if obj:IsA("BasePart") then return obj.Position end
		if obj:IsA("Model") then
			local p = obj:FindFirstChildWhichIsA("BasePart", true)
			return p and p.Position or nil
		end
		local p = obj:FindFirstChildWhichIsA("BasePart", true)
		return p and p.Position or nil
	end
	
	local function ignorados()
		local lista = {}
		if player.Character then table.insert(lista, player.Character) end
		local pasta = pastaCandy()
		if pasta then table.insert(lista, pasta) end
		return lista
	end
	
	-- Filtro de subsolo: ignora doces cobertos por chao/peca solida.
	local function doceAcessivel(pos)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = ignorados()
		params.IgnoreWater = true
	
		local origem = pos + Vector3.new(0, ALTURA_RAYCAST, 0)
		local resultado = workspace:Raycast(origem, Vector3.new(0, -ALTURA_RAYCAST, 0), params)
		-- Se bater no chao ANTES da altura do doce, o doce esta enterrado.
		if resultado and resultado.Position.Y > pos.Y + MARGEM_SUBSOLO then
			return false
		end
		return true
	end
	
	local function adicionarPonto(pos)
		for _, ponto in ipairs(pontos) do
			if (ponto - pos).Magnitude <= RAIO_MESMO_SPAWN then
				return false
			end
		end
		table.insert(pontos, pos)
		return true
	end
	
	local function conectarPasta()
		local pasta = pastaCandy()
		if pasta == monitorada then return end
		if conexaoPasta then conexaoPasta:Disconnect() end
		monitorada = pasta
		conexaoPasta = nil
		if pasta then
			conexaoPasta = pasta.DescendantAdded:Connect(function() end)
		end
	end
	
	-- Todos os doces carregados, sem limite artificial de distancia.
	local function varrerDoces()
		conectarPasta()
		local pasta = pastaCandy()
		local doces = {}
		if not pasta then return doces end
		for _, obj in ipairs(pasta:GetDescendants()) do
			if ehDoce(obj) then
				local pos = posicaoDoce(obj)
				if pos and doceAcessivel(pos)
					and (not tentativasFalhas[obj] or os.clock() >= tentativasFalhas[obj]) then
					table.insert(doces, {obj = obj, pos = pos})
				end
			end
		end
		return doces
	end
	
	-- ------------------------------------------------------------------
	-- Movimento
	-- ------------------------------------------------------------------
	local function personagem()
		local char = player.Character
		if not char then return nil end
		local root = char:FindFirstChild("HumanoidRootPart")
		local hum = char:FindFirstChildWhichIsA("Humanoid")
		if not root or not hum or hum.Health <= 0 then return nil end
		return char, hum, root
	end
	
	local function altura(hum, root, char)
		local y = hum.HipHeight + root.Size.Y * 0.5 + 0.35
		if hum.RigType == Enum.HumanoidRigType.R6 then
			local leg = char:FindFirstChild("Left Leg")
			if leg then y += leg.Size.Y end
		end
		return math.max(3, y)
	end
	
	-- Desloca o personagem preservando o offset do rig (metodo do candy.lua).
	local function mover(char, root, position)
		if player.Character ~= char or not root.Parent then
			return false
		end
		char:PivotTo(CFrame.new(position - root.Position) * char:GetPivot())
		root.AssemblyLinearVelocity = Vector3.zero
		root.AssemblyAngularVelocity = Vector3.zero
		return true
	end
	
	local function teleportar(pos)
		if not ativo or not vivo then return false end
		local char, hum, root = personagem()
		if not char then return false end
		return mover(char, root, pos)
	end
	
	local function chaoProximo(pos)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = ignorados()
		params.IgnoreWater = true
	
		local result = workspace:Raycast(pos + Vector3.new(0, 32, 0), Vector3.new(0, -90, 0), params)
		if result then return result.Position + Vector3.new(0, ALTURA_PONTO, 0) end
		return pos + Vector3.new(0, ALTURA_PONTO, 0)
	end
	
	-- ------------------------------------------------------------------
	-- Exploracao por arvores (Workspace.Map.Tree)
	-- ------------------------------------------------------------------
	local function embaralhar(lista)
		for i = #lista, 2, -1 do
			local j = random:NextInteger(1, i)
			lista[i], lista[j] = lista[j], lista[i]
		end
	end
	
	local function construirRotaArvores()
		rotaArvores = {}
		rotaIndex = 1
	
		local mapa = workspace:FindFirstChild("Map")
		local arvores = mapa and mapa:FindFirstChild(TREE_FOLDER)
		if not arvores then
			rotaRefresh = os.clock() + 3
			return false
		end
	
		local novas = {}
		for i, arvore in ipairs(arvores:GetChildren()) do
			if arvore:IsA("Model") or arvore:IsA("BasePart") then
				local pos
				if arvore:IsA("BasePart") then
					pos = arvore.Position - Vector3.new(0, arvore.Size.Y / 2, 0)
				else
					local maisBaixo = math.huge
					for _, parte in ipairs(arvore:GetDescendants()) do
						if parte:IsA("BasePart") then
							local y = parte.Position.Y - parte.Size.Y / 2
							if y < maisBaixo then
								maisBaixo = y
								pos = Vector3.new(parte.Position.X, y, parte.Position.Z)
							end
						end
					end
				end
				if pos then table.insert(novas, pos) end
			end
			if i % 50 == 0 then task.wait() end
		end
	
		rotaArvores = novas
		embaralhar(rotaArvores)
		rotaRefresh = os.clock() + REFRESH_ROTA
		return #rotaArvores > 0
	end
	
	-- Teleporta para o chao ao lado de uma arvore.
	local function explorarArvore()
		local char, hum, root = personagem()
		if not char then return false end
	
		if os.clock() >= rotaRefresh or #rotaArvores == 0 then
			if not construirRotaArvores() then return false end
		end
	
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
	
		local exclusoes = {char}
		local pasta = pastaCandy()
		if pasta then table.insert(exclusoes, pasta) end
		params.FilterDescendantsInstances = exclusoes
		params.IgnoreWater = false
	
		for _ = 1, math.min(#rotaArvores, 12) do
			if rotaIndex > #rotaArvores then
				embaralhar(rotaArvores)
				rotaIndex = 1
			end
	
			local base = rotaArvores[rotaIndex]
			rotaIndex = rotaIndex + 1
	
			local offsets = {
				Vector3.new(TREE_DISTANCE, 0, 0),
				Vector3.new(-TREE_DISTANCE, 0, 0),
				Vector3.new(0, 0, TREE_DISTANCE),
				Vector3.new(0, 0, -TREE_DISTANCE),
			}
	
			for _, offset in ipairs(offsets) do
				local origem = base + offset + Vector3.new(0, 40, 0)
				local hit = workspace:Raycast(origem, Vector3.new(0, -100, 0), params)
				if hit and hit.Normal.Y > 0.65 and hit.Material ~= Enum.Material.Water then
					local destino = hit.Position + Vector3.new(0, altura(hum, root, char), 0)
					if mover(char, root, destino) then
						return true
					end
				end
			end
		end
	
		return false
	end
	
	-- ------------------------------------------------------------------
	-- Coleta
	-- ------------------------------------------------------------------
	local function coletar(doce)
		if not ativo or not vivo or not doce.obj or not doce.obj.Parent then return false end
		local posInicial = doce.pos
		if not posInicial or not doceAcessivel(posInicial) then return false end
	
		local inicio = os.clock()
		local pasta = pastaCandy()
	
		while vivo and ativo and doce.obj.Parent and pasta
			and doce.obj:IsDescendantOf(pasta)
			and os.clock() - inicio < TEMPO_TENTATIVA do
			local pos = posicaoDoce(doce.obj)
			if not pos or not doceAcessivel(pos) then break end
			if not teleportar(pos + Vector3.new(0, 1.6, 0)) then break end
			task.wait(INTERVALO_TENTATIVA)
		end
	
		-- Somente considera coletado se o Candy saiu da pasta.
		local coletado = not doce.obj.Parent or not (pasta and doce.obj:IsDescendantOf(pasta))
	
		if coletado and adicionarPonto(posInicial) then
			logImportante(string.format(
				"[HPX CANDY NOVO SPAWN] X: %.2f | Y: %.2f | Z: %.2f | Total: %d",
				posInicial.X, posInicial.Y, posInicial.Z, #pontos
				))
		end
		if not coletado then
			tentativasFalhas[doce.obj] = os.clock() + PAUSA_DOCE_FALHOU
		end
		return coletado
	end
	
	-- Doces visiveis tem prioridade sobre a rota de exploracao.
	local function tentarDocesDisponiveis()
		local doces = varrerDoces()
		if #doces == 0 then return false end
	
		local _, _, root = personagem()
		if not root then return false end
	
		table.sort(doces, function(a, b)
			return (a.pos - root.Position).Magnitude < (b.pos - root.Position).Magnitude
		end)
	
		for _, info in ipairs(doces) do
			if not ativo or not vivo then return true end
			local pasta = pastaCandy()
			if pasta and info.obj.Parent and info.obj:IsDescendantOf(pasta) and doceAcessivel(info.pos) then
				coletar(info)
			end
		end
		return true
	end
	
	-- ------------------------------------------------------------------
	-- Loop principal
	-- ------------------------------------------------------------------
	local function rodada()
		if rodando then return end
		rodando = true
		task.spawn(function()
			while vivo and ativo do
				-- Primeiro percorre todos os CandyTemplate ja detectados.
				if tentarDocesDisponiveis() then
					task.wait(0.08)
				else
					-- Sem doces carregados: visita pontos conhecidos/arvores e re checa.
					local rota = table.clone(pontos)
					embaralhar(rota)
	
					for _, ponto in ipairs(rota) do
						if not vivo or not ativo then break end
						if #varrerDoces() > 0 then break end
	
						-- A cada N spawns conhecidos, explora uma arvore.
						if visitasConhecidas >= VISITAS_CONHECIDAS_ANTES_ARVORE then
							visitasConhecidas = 0
							if explorarArvore() then
								task.wait(ESPERA_CARREGAR)
								if #varrerDoces() > 0 then break end
							end
						else
							visitasConhecidas = visitasConhecidas + 1
						end
	
						-- Aproximar-se faz o cliente poder receber objetos daquela regiao.
						teleportar(chaoProximo(ponto))
						task.wait(ESPERA_CARREGAR)
						if #varrerDoces() > 0 then break end
	
						-- Explora arredores alternados para cobrir mais regioes
						-- onde o jogo cria os doces de acordo com a posicao do jogador.
						for visita = 1, VISITAS_EXTRAS_POR_PONTO do
							if not vivo or not ativo then break end
							local angulo = random:NextNumber() * math.pi * 2
							local deslocamento = Vector3.new(
								math.cos(angulo) * RAIO_ANALISE_EXTRA,
								0,
								math.sin(angulo) * RAIO_ANALISE_EXTRA
							)
							teleportar(chaoProximo(ponto + deslocamento))
							task.wait(ESPERA_CARREGAR)
							if #varrerDoces() > 0 then break end
						end
	
						task.wait(ESPERA_PONTO)
					end
				end
			end
			rodando = false
		end)
	end
	
	local function atualizarVisual()
		if not botao.Parent then return end
		botao.BackgroundColor3 = ativo and COR_ATIVA or corOriginal
	end
	
	local function alternar()
		if not vivo then return end
		ativo = not ativo
		atualizarVisual()
		if ativo then
			conectarPasta()
			rodada()
		end
	end
	
	-- ------------------------------------------------------------------
	-- Atalho exatamente no estilo do sistema HPX Bones
	-- ------------------------------------------------------------------
	local keyButton = botao:FindFirstChild("keybutton", true)
		or botao:FindFirstChild("keybuton", true)
		or botao:FindFirstChild("key", true)
		or botao:FindFirstChild("tecla", true)
	
	-- Se o keybutton for um Frame, procura o campo dentro dele.
	if keyButton and not (keyButton:IsA("TextBox") or keyButton:IsA("TextButton")) then
		keyButton = keyButton:FindFirstChildWhichIsA("TextBox", true)
			or keyButton:FindFirstChildWhichIsA("TextButton", true)
	end
	
	-- Registro de atalhos: usa _G/getgenv para ser compartilhado com
	-- Bones/Lobo/Potions mesmo com o codigo ofuscado.
	local function registroAtalhos()
		local env = nil
		if type(getgenv) == "function" then
			env = getgenv()
		elseif type(getfenv) == "function" then
			env = getfenv(0)
		end
		if type(env) == "table" then
			env.HPX_Atalhos = env.HPX_Atalhos or {}
			return env.HPX_Atalhos
		end
		_G.HPX_Atalhos = _G.HPX_Atalhos or {}
		return _G.HPX_Atalhos
	end
	
	local TECLA_ATIVAR = nil
	local numeros = {"Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"}
	local atualizandoTextoTecla = false
	local avisoSequencia = 0
	local capturando = false
	
	local function nomeVisivel(keyCode)
		if not keyCode then return nil end
		for i, nome in ipairs(numeros) do
			if keyCode.Name == nome then return tostring(i - 1) end
		end
		return keyCode.Name
	end
	
	local function atualizarTextoTecla()
		if not keyButton or not keyButton.Parent then return end
		atualizandoTextoTecla = true
		keyButton.Text = TECLA_ATIVAR and nomeVisivel(TECLA_ATIVAR) or "-"
		atualizandoTextoTecla = false
	end
	
	local function obterTecla(texto)
		local nome = string.upper((texto or ""):sub(1, 1))
		if #nome ~= 1 then return nil end
		local codigo = string.byte(nome)
		if not codigo or not ((codigo >= 48 and codigo <= 57) or (codigo >= 65 and codigo <= 90)) then
			return nil
		end
		if codigo >= 48 and codigo <= 57 then
			return Enum.KeyCode[numeros[codigo - 47]]
		end
		return Enum.KeyCode[nome]
	end
	
	local function donoDaTecla(nome)
		local reg = registroAtalhos()
		if typeof(reg) == "Instance" then
			local v = reg:FindFirstChild(nome)
			return v and v:IsA("StringValue") and v.Value or nil
		end
		if type(reg) == "table" then
			local v = reg[nome]
			return typeof(v) == "Instance" and v:IsA("StringValue") and v.Value or v
		end
	end
	
	local function gravarDono(nome, dono)
		local reg = registroAtalhos()
		if typeof(reg) == "Instance" then
			local v = reg:FindFirstChild(nome)
			if dono then
				if not v then
					v = Instance.new("StringValue")
					v.Name = nome
					v.Parent = reg
				end
				if v:IsA("StringValue") then v.Value = dono end
			elseif v and v:IsA("StringValue") and v.Value == IDENTIFICADOR then
				v:Destroy()
			end
		elseif type(reg) == "table" then
			if dono or reg[nome] == IDENTIFICADOR then reg[nome] = dono end
		end
	end
	
	local function definirTecla(keyCode)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then return end
		local nome = nomeVisivel(keyCode)
		local dono = donoDaTecla(nome) or donoDaTecla(keyCode.Name)
		if dono and dono ~= "" and dono ~= IDENTIFICADOR then
			avisoSequencia = avisoSequencia + 1
			local seq = avisoSequencia
			if keyButton then
				atualizandoTextoTecla = true
				keyButton.Text = "USADA"
				atualizandoTextoTecla = false
			end
			task.delay(1.2, function()
				if vivo and seq == avisoSequencia then atualizarTextoTecla() end
			end)
			return
		end
		avisoSequencia = avisoSequencia + 1
		if TECLA_ATIVAR then
			local antiga = nomeVisivel(TECLA_ATIVAR)
			gravarDono(antiga, nil)
			if antiga ~= TECLA_ATIVAR.Name then gravarDono(TECLA_ATIVAR.Name, nil) end
		end
		TECLA_ATIVAR = keyCode
		gravarDono(nome, IDENTIFICADOR)
		atualizarTextoTecla()
		if keyButton and keyButton:IsA("TextBox") and keyButton:IsFocused() then
			keyButton:ReleaseFocus()
		end
	end
	
	if keyButton and keyButton:IsA("TextBox") then
		keyButton.TextEditable = true
		keyButton.ClearTextOnFocus = false
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
		table.insert(conexoes, keyButton:GetPropertyChangedSignal("Text"):Connect(function()
			if atualizandoTextoTecla then return end
			local primeiro = string.upper(keyButton.Text or ""):sub(1, 1)
			local tecla = obterTecla(primeiro)
			atualizandoTextoTecla = true
			keyButton.Text = tecla and primeiro or ""
			atualizandoTextoTecla = false
			if tecla then definirTecla(tecla) end
		end))
		table.insert(conexoes, keyButton.FocusLost:Connect(atualizarTextoTecla))
	elseif keyButton and keyButton:IsA("TextButton") then
		local inicial = obterTecla(keyButton.Text)
		if inicial then definirTecla(inicial) end
		table.insert(conexoes, keyButton.Activated:Connect(function()
			capturando = true
			keyButton.Text = "..."
		end))
	end
	
	table.insert(conexoes, botao.Activated:Connect(function()
		if capturando then return end
		alternar()
	end))
	
	table.insert(conexoes, UIS.InputBegan:Connect(function(input, processado)
		if not vivo or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		if capturando then
			capturando = false
			local tecla = obterTecla(nomeVisivel(input.KeyCode))
			if tecla then definirTecla(tecla) else atualizarTextoTecla() end
			return
		end
		if processado or UIS:GetFocusedTextBox() then return end
		if TECLA_ATIVAR and input.KeyCode == TECLA_ATIVAR then alternar() end
	end))
	
	_G.HPX_CandyRota_Parar = function()
		vivo, ativo = false, false
		if TECLA_ATIVAR then
			local nome = nomeVisivel(TECLA_ATIVAR)
			gravarDono(nome, nil)
			if nome ~= TECLA_ATIVAR.Name then gravarDono(TECLA_ATIVAR.Name, nil) end
		end
		atualizarVisual()
		if conexaoPasta then conexaoPasta:Disconnect() end
		for _, c in ipairs(conexoes) do c:Disconnect() end
	end
	
	table.insert(conexoes, botao.Destroying:Connect(function()
		if vivo then _G.HPX_CandyRota_Parar() end
	end))
	
	atualizarTextoTecla()
	atualizarVisual()
	conectarPasta()
	
end
local function XARQ_fake_script() -- Fake Script: StarterGui.ScreenGui.mainFrame.voxUp.RoVibes.BoneButton.LocalScript
