	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")
	
	local player = Players.LocalPlayer
	
	local OSSOS_NECESSARIOS = 10
	
	local RAIO_SCAN = 2200
	local PASSO_SCAN = 450
	
	local RAIO_SCAN_FINO = 1000
	local PASSO_SCAN_FINO = 150
	
	local RAIO_SCAN_EXTRA = 2200
	local PASSO_SCAN_EXTRA = 110
	
	local TEMPO_ANALISE = 0.25
	local TEMPO_ANALISE_FINA = 0.3
	local TEMPO_ANALISE_EXTRA = 0.35
	
